50	  /// and the initials chip shows — the same fallback path as an unknown GitHub login.
51	  private static func gravatar(email: String, pixelSize: Int) -> URL? {
52	    let normalized = email.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
