60	    guard
61	      let encoded = login.addingPercentEncoding(withAllowedCharacters: .urlPathAllowed),
62	      !encoded.isEmpty
63	    else { return nil }
64	    return URL(string: "https://github.com/\(encoded).png?size=\(pixelSize)")
65	  }
