import AppKit
import SwiftUI
import XCTest

@testable import Workroom

/// View-layer harness for splits (issue #3). Hosts the real pane renderer in an off-screen `NSWindow`
/// and inspects the AppKit hierarchy after driving the model — so it verifies what unit tests on the
/// model can't: that the right terminal surfaces are actually **mounted in the window** with sensible
/// frames after split / close / focus changes.
///
/// This is the regression net for the close-a-split-pane blank bug: that bug left the surviving
/// surface in a detached container (no window) at the wrong size. Counting window-mounted
/// `GhosttySurfaceView`s here catches exactly that. Runs in the normal `make app-test` gate (no UI-
/// automation entitlement needed — unlike XCUITest, which the CI/dev machine must be granted).
@MainActor
final class PaneRenderingTests: XCTestCase {
  private let target = TerminalTarget(
    id: "wr|/p|panes", title: "panes", path: "/tmp", isMissing: false)

  private func makeSessions() -> TerminalSessions {
    let s = TerminalSessions()
    // Mount real `GhosttySurfaceView`s (so the AppKit hierarchy assertions below are meaningful) but
    // with `spawnsSurface: false` — no libghostty Metal renderer / login shell. Hosting live surfaces
    // in the headless CI unit-test host crashed XCTest's post-test memory checker on teardown; the
    // view-mount/layout path this suite verifies needs no live surface.
    s.makeView = { _, cwd, _ in GhosttySurfaceView(workingDirectory: cwd, spawnsSurface: false) }
    return s
  }

  /// Host the content (the same layout decision `WorkroomTerminalsView` makes) in a window.
  private func host(_ sessions: TerminalSessions) -> (NSWindow, NSView) {
    let root = TestPaneHost(target: target, sessions: sessions)
      .environmentObject(AppStore())
      .environmentObject(sessions.agentManager)
    let hosting = NSHostingView(rootView: root)
    hosting.frame = NSRect(x: 0, y: 0, width: 900, height: 600)
    let window = NSWindow(
      contentRect: hosting.frame, styleMask: [.titled], backing: .buffered, defer: false)
    // ARC owns `window`; a programmatic NSWindow defaults `isReleasedWhenClosed` to true, so the
    // `window.close()` in each test's `defer` would send a second release on top of ARC's — an
    // over-release that corrupts the heap. Opt out so ARC is the sole owner.
    window.isReleasedWhenClosed = false
    window.contentView = hosting
    window.makeKeyAndOrderFront(nil)
    return (window, hosting)
  }

  /// All `GhosttySurfaceView`s under `view` that are actually attached to a window (i.e. rendered).
  private func mountedSurfaces(in view: NSView) -> [GhosttySurfaceView] {
    var found: [GhosttySurfaceView] = []
    func walk(_ v: NSView) {
      if let s = v as? GhosttySurfaceView, s.window != nil { found.append(s) }
      v.subviews.forEach(walk)
    }
    walk(view)
    return found
  }

  /// Poll the runloop until SwiftUI commits and the mounted-surface count settles to `expected`.
  @discardableResult
  private func waitForSurfaces(in view: NSView, count expected: Int, timeout: TimeInterval = 3)
    -> [GhosttySurfaceView]
  {
    let deadline = Date().addingTimeInterval(timeout)
    while Date() < deadline {
      view.layoutSubtreeIfNeeded()
      if mountedSurfaces(in: view).count == expected { break }
      RunLoop.current.run(until: Date().addingTimeInterval(0.05))
    }
    view.layoutSubtreeIfNeeded()
    return mountedSurfaces(in: view)
  }

  func testSoloRendersOnePane() {
    let s = makeSessions()
    s.addTab(for: target)
    let (window, view) = host(s)
    defer {
      s.reapAll()
      window.close()
    }  // free surfaces so their render threads stop
    XCTAssertEqual(waitForSurfaces(in: view, count: 1).count, 1)
  }

  func testSplitRendersTwoPanes() {
    let s = makeSessions()
    s.addTab(for: target)
    s.splitFocusedPane(for: target, orientation: .horizontal)
    let (window, view) = host(s)

import XCTest

@testable import Workroom

/// Live History refresh (issue #59 follow-up): a commit / bookmark / ref move in a project's VCS
/// metadata dir trips the per-project watcher → `handleRootBranchChange`, which now repaints the
/// History log **when the inspector is visible, showing History, and its target is in that project** —
/// independent of whether the branch label changed (a plain commit usually leaves it unchanged). Also
/// covers the app-refocus safety net `refreshHistoryIfActive`.
///
/// The commit log itself is driven through an injected `HistoryModel` backed by a counting provider,
/// so "did a refresh fire?" is observable as a `log` call count — no real repo needed for the gating
/// logic. `runBlocking` reads run off-main, so each assertion awaits `commitHistory.awaitCurrentLoad`.
///
/// All three halves of the gate are pinned **per store** — `inspectorVisibleOverrideForTesting`,
/// `isolatesInspectorSectionForTesting` and `isolatesInspectorLayoutForTesting` (the collapse flag,
/// added when History joined the Changes stack) — never by writing the shared inspector settings: the parallel
/// workers share one UserDefaults domain, so this class used to leave its `showInspector` /
/// `inspector.activeSection` values inside whatever unrelated class ran beside it. (The old
/// save/restore here couldn't have helped even in serial: it restored `"activeInspectorSection"`,
/// which is not the key — the real one is `"inspector.activeSection"`.)
@MainActor
final class HistoryLiveRefreshTests: XCTestCase {

  // MARK: harness

  /// Counts `log` calls (the observable "a load fired" signal). Lock-guarded + `@unchecked Sendable`
  /// because `log` runs off-main via `runBlocking`; tests serialize with `awaitCurrentLoad`.
  private final class CountingProvider: VCSProviding, @unchecked Sendable {
    private let lock = NSLock()
    private var _count = 0
    var logCount: Int { lock.withLock { _count } }
    func log(root: URL, limit: Int) throws -> VCSHistoryPage {
      lock.withLock { _count += 1 }
      return VCSHistoryPage(commits: [], reachedEnd: true)
    }
    func changeset(root: URL, commitID: String) async throws -> VCSChangeset {
      throw VCSError.io("x")
    }
    func fileDiff(root: URL, commitID: String, path: String) async throws -> String {
      throw VCSError.io("x")
    }
    func workingFileDiff(root: URL, path: String, base: VCSWorkingDiffBase) async throws -> String {
      throw VCSError.io("x")
    }
    func fileContent(root: URL, rev: String, path: String) async throws -> String? { nil }
    func currentRef(root: URL) async throws -> VCSRef { .none }
  }

  private func project(_ path: String, workrooms: [String]) -> Project {
    Project(
      path: path, vcs: "git",
      workrooms: workrooms.map {
        Workroom(name: $0, path: "\(path)/\($0)", vcsName: "workroom/\($0)", warnings: [])
      })
  }

  private func wr(_ name: String, in path: String) -> SidebarID {
    .workroom(project: path, name: name)
  }

  /// A store with a counting `commitHistory`, one workroom-with-a-tab selected, the inspector visible
  /// and showing History (so `inspectorTargetID` is non-nil and the model is focused → `root != nil`,
  /// the precondition for `refresh` to actually load). History is a sub-section of the **Changes**
  /// pane, so "showing" is that pane being active AND the section expanded — the collapse flag is
  /// pinned here rather than trusted, because it hydrates from the shared `inspectorLayout` pref that
  /// any other class (or worker) may have left collapsed. Returns the store + the counting provider.
  private func activeHistoryStore(
    projects: [Project], select path: String, workroom name: String
  ) async -> (AppStore, CountingProvider) {
    let provider = CountingProvider()
    let store = AppStore(commitHistory: HistoryModel(resolve: { _ in provider }))
    store.terminals.makeView = { _, cwd, command in
      GhosttySurfaceView(workingDirectory: cwd, command: command, spawnsSurface: false)
    }
    store.projects = projects
    store.inspectorVisibleOverrideForTesting = true
    store.isolatesInspectorSectionForTesting = true
    store.isolatesInspectorLayoutForTesting = true
    store.activeInspectorSection = .changes
    store.historySectionCollapsed = false
    // Give the selection a tab so `selectionHasTabs` (and thus `inspectorTargetID`) is non-nil.
    store.terminals.addTab(for: store.target(for: wr(name, in: path))!)
    // Selecting fires the didSet that focuses `commitHistory` (History showing) → the first load.
    store.selectedTargetID = wr(name, in: path)
    await store.commitHistory.awaitCurrentLoad()
    return (store, provider)
  }

  // MARK: live watcher path

  func testMetadataChangeRefreshesHistoryEvenWhenLabelUnchanged() async {
    let (store, provider) = await activeHistoryStore(
      projects: [project("/a", workrooms: ["solo"])], select: "/a", workroom: "solo")
    XCTAssertEqual(store.inspectorTargetID, wr("solo", in: "/a"))
    let before = provider.logCount

    store.handleRootBranchChange(projectID: store.projects[0].id)
    await store.commitHistory.awaitCurrentLoad()

    XCTAssertEqual(
      provider.logCount, before + 1,
      "a metadata change for the shown workroom's project must refresh History, even though a normal "
        + "commit leaves the branch label unchanged (the placement-before-the-label-return guard)")
  }

  func testMetadataChangeInOtherProjectDoesNotRefresh() async {
    let (store, provider) = await activeHistoryStore(
      projects: [project("/a", workrooms: ["solo"]), project("/b", workrooms: ["other"])],
      select: "/a", workroom: "solo")
    let before = provider.logCount
    let otherProject = store.projects.first { $0.path == "/b" }!

    store.handleRootBranchChange(projectID: otherProject.id)
    await store.commitHistory.awaitCurrentLoad()

    XCTAssertEqual(
      provider.logCount, before, "a change in a DIFFERENT project must not refresh this History")
  }

/// unclamped body grew the card arbitrarily tall on a long commit message. All of it is one click
/// away in the detail view. Rendered inside a `.popover`.
///
/// Deliberately `internal`, not `private`: XCUITest can't drive `.onHover`, so the card's contents are
/// covered by a view-level test that constructs it directly (`HistoryCommitCardTests`).
struct HistoryCommitCard: View {
  let commit: VCSCommit
  /// What push state was measured against, for the unpushed marker's tooltip.
  var pushScope: VCSPushScope?
  private let theme = ThemeService.shared

  /// Whether the card states "Not pushed" — the same rule the row's chip uses. A named property rather
  /// than an inline condition because a unit-test process has no accessibility tree for a hosted
  /// SwiftUI view (macOS builds it only for a live AX client), so this is the only way to assert the
  /// card's wiring; `HistoryCommitCardTests` covers it, and the row's XCUITest covers the visual.
  var showsUnpushedMarker: Bool { commit.showsUnpushedBadge }

  private static let dateFormatter: DateFormatter = {
    let f = DateFormatter()
    f.dateStyle = .medium
    f.timeStyle = .short
    return f
  }()

  var body: some View {
    VStack(alignment: .leading, spacing: 5) {
      Text(commit.summary.isEmpty ? "(no description)" : commit.summary)
        .font(.callout.weight(.semibold))
        .foregroundStyle(commit.summary.isEmpty ? .secondary : .primary)
        .textSelection(.enabled)
        .fixedSize(horizontal: false, vertical: true)
      HStack(spacing: 10) {
        // Identity, styled like the detail header: change-id (purple, jj only) + commit-id (blue),
        // monospaced.
        if let changeID = commit.changeID {
          Text(changeID)
            .font(.system(.caption, design: .monospaced))
            .foregroundStyle(.purple)
        }
        Text(commit.shortID)
          .font(.system(.caption, design: .monospaced))
          .foregroundStyle(.blue)
        // Bookmarks/branches, as the same gray capsules the rows use, left of the author — mirrors
        // `ChangesetDetailView.header`.
        ForEach(commit.refs, id: \.self) { ref in
          Text(ref)
            .font(.caption2)
            .lineLimit(1)
            .truncationMode(.tail)
            .padding(.horizontal, 5).padding(.vertical, 1)
            .background(.quaternary, in: Capsule())
            .help("Bookmark / branch")
        }
        if !commit.authorNamesDisplay.isEmpty {
          Label {
            Text(commit.authorNamesDisplay)
          } icon: {
            AvatarStack(
              subjects: commit.authors.map { AvatarSubject(author: $0, pixelSize: 54) }, size: 18)
          }
        }
        Label(Self.dateFormatter.string(from: commit.timestamp), systemImage: "clock")
        if commit.parentIDs.count > 1 {
          Label("Merge", systemImage: "arrow.triangle.merge")
        }
        if showsUnpushedMarker {
          // Spelled out here rather than reusing the row's icon capsule: the card has room for words,
          // and it mirrors how the changeset detail header states the same fact.
          Label("Not pushed", systemImage: "arrow.up")
            .foregroundStyle(theme.tokens.warning)
            .help(VCSPushScope.unpushedHelp(pushScope))
            .accessibilityIdentifier("HistoryCardUnpushed")
        }
        Spacer(minLength: 0)
      }
      .font(.caption).foregroundStyle(.secondary).lineLimit(1)
    }
    .padding(.horizontal, 12).padding(.vertical, 10)
    .frame(width: 420, alignment: .leading)
  }
}

/// One divergent-copy row inside the expander: jj's `id/N` label + summary + relative time, with the
/// SAME hover / selected highlight as a `HistoryRow` — a full-width band (content indented under the
/// parent). Selected when its changeset is the focused content tab; a single click opens it.
private struct DivergentSiblingRow: View {
  let sibling: VCSCommit
  /// Opens a commit's changeset detail (preview) — the parent row's `open`, siblings only preview.
  let open: (_ commit: VCSCommit, _ persist: Bool) -> Void
  @EnvironmentObject var store: AppStore

