  let m = capped(FakeProvider(all: (1...20).map { commit("\($0)") }), pageSize: 10, maxWindow: 3)
  m.focus(url)
  await m.awaitCurrentLoad()
  XCTAssertEqual(m.commits.count, 10)
  XCTAssertEqual(m.windowCap, 10)
}

